    const p1 = planRebalance({ scan: { ...scanBase, sources: [src(8453, 'Base', 'USDC', 500, 500), src(1, 'Ethereum', 'ETH', 0.01, 20)] }, rates, earning })
    const p1job = p1.kind === 'plan' ? compileJobAsk(p1.ask) : null
