    const p2 = planRebalance({ scan: { ...scanBase, sources: [src(8453, 'Base', 'USDC', 500, 500), src(8453, 'Base', 'ETH', 0.02, 40)] }, rates, earning })
    const p2gas = p2.kind === 'plan' ? p2.moves[0]?.gasLeg : null
