    const p3 = planRebalance({ scan: { ...scanBase, sources: [src(8453, 'Base', 'USDC', 500, 500), src(42161, 'Arbitrum', 'ETH', 0.2, 400)] }, rates, earning })
    const p3aave = p3.kind === 'plan' ? p3.moves.find((m) => m.venue === 'aave') : undefined
